```{ojs}
result = {
  // Rebuild the parent sets from the chosen edges.
  const parents = Object.fromEntries(sl.nodes.map(d => [d.id, []]));
  for (const choice of Object.values(edges)) if (choice !== "none") { const [u, , v] = choice.split(" "); parents[v].push(u); }
  // Acyclic? Repeatedly remove nodes whose parents are all removed (as in is_acyclic).
  let left = new Set(Object.keys(parents)), progress = true;
  while (progress) { progress = false;
    for (const x of [...left]) if (parents[x].every(p => !left.has(p))) { left.delete(x); progress = true; } }
  if (left.size) return {cyclic: true, parents};
  // Decomposable score: one precomputed term per variable.
  const score = d3.sum(Object.entries(parents), ([x, pa]) => sl.table[`${x}|${[...pa].sort().join(",")}`]);
  // Markov equivalence: compare skeletons and v-structures with the true graph.
  const skel = g => new Set(Object.entries(g).flatMap(([x, pa]) => pa.map(p => [p, x].sort().join(""))));
  const vstr = g => { const s = skel(g);
    return new Set(Object.entries(g).flatMap(([c, pa]) => pa.flatMap((a, i) => pa.slice(i + 1)
      .filter(b => !s.has([a, b].sort().join(""))).map(b => [a, b].sort().join("") + ">" + c)))); };
  const same = (A, B) => A.size === B.size && [...A].every(e => B.has(e));
  const equivalent = same(skel(parents), skel(sl.truth)) && same(vstr(parents), vstr(sl.truth));
  return {cyclic: false, parents, score, diff: score - sl.trueScore, equivalent};
}
```

